#!/usr/bin/env python3
"""Audit all saved captures with exact GF(2) values and independent normal CDF."""
from pathlib import Path
import argparse,struct,json,math,hashlib
p=argparse.ArgumentParser();p.add_argument('result',type=Path);p.add_argument('--output',type=Path,required=True);a=p.parse_args();R=Path(__file__).resolve().parent;d=json.loads(a.result.read_text());fixture=json.loads((R/'scientific_operator_witness.json').read_text());prefix=(R/'study_input_f64.bin').read_bytes();gold=struct.unpack('<393236d',(R/'study_math_expected_f64.bin').read_bytes());n=fixture['stage_outputs'];pr=struct.unpack('<112d',prefix);distance=int(pr[3]);xs=[(i+1)*distance for i in range(n)]+list(map(int,pr[98:]));U=2**32-1;probs=[((min(x,U-x)+.5)/U if x<2**31 else 1-(min(x,U-x)+.5)/U) for x in xs];rows=[]
for model,md in d['models'].items():
 for t in md['trials']:
  f=Path(t['output_artifact']['saved_path']);raw=f.read_bytes();assert len(raw)==393348*8 and raw[:896]==prefix;assert hashlib.sha256(raw).hexdigest()==t['output_artifact']['sha256'];v=struct.unpack('<393236d',raw[896:]);assert v[:n]==gold[:n];normal=v[n:];errs=[abs(x-y) for x,y in zip(normal,gold[n:])];assert all(math.isfinite(x) and abs(x-y)<=2e-5+2e-6*abs(y) for x,y in zip(normal,gold[n:]));cdfmax=max(abs(.5*math.erfc(-x/math.sqrt(2))-p) for x,p in zip(normal,probs));assert cdfmax<=2e-6;assert all(x<=y for x,y in zip(normal[:n-1],normal[1:n]));probes=normal[n:];assert all(x<=y for x,y in zip(probes,probes[1:]));lookup=dict(zip(map(int,pr[98:]),probes));symmax=max(abs(z+lookup[U-x]) for x,z in lookup.items() if U-x in lookup);assert symmax==0
  rows.append({'model':model,'trial':t['trial'],'sha256':t['output_artifact']['sha256'],'input_prefix_exact':True,'qrng_bitmatrix_exact_values':n,'normal_inverse_max_abs_error':max(errs),'normal_cdf_max_error':cdfmax,'primary_quantiles_monotonic':True,'probe_symmetry_max_error':symmax,'source_qrng_l1':t['qrng_source_l1'],'source_moro_l1':t['icnd_source_l1']})
assert len(rows)==20
out={'benchmark':'qrg','result':str(a.result.resolve()),'fixture':fixture,'all20_pass':True,'audited_artifacts':20,'outputs_per_artifact':393236,'exact_input_prefix_count':112,'rows':rows,'descriptors':{'dimensions':3,'points_per_dimension':65537,'independent_probability_grid_points':196611,'normal_probe_count':14,'qrng_dimension_division_in_julia_mapping':True,'native_qrng_threads':[85,3],'native_qrng_blocks':193,'native_icnd_threads':128,'native_icnd_blocks':128,'julia_primary_threads':256,'julia_primary_blocks':769},'scope':'Pointwise digital-sequence/normal-approximation accuracy and finite-prefix marginal balance only; ICND does not consume QRNG output. Not integration accuracy or RNG distribution certification.'};a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'artifacts':20,'normal_max_abs':max(r['normal_inverse_max_abs_error'] for r in rows),'cdf_max':max(r['normal_cdf_max_error'] for r in rows),'all20_pass':True}))
